import { KINDS, type Binding, type Context, type Def, type Kind, type Resource, type Var } from './resource.ts'
import { isRef, type Compose, type Ref } from './compose.ts'
import type { ComposeSpecification } from './types.d.ts'

/** A compose file. `name` is the project name, which the generated types predate. */
export type Spec = ComposeSpecification & { name: string }

export interface Options {
  /** Values for the `Var`s the definitions read. */
  vars?: readonly Binding<any>[]
  build?: boolean
}

/** Every stack's file, and the order to bring them up in. */
export interface Project {
  /** Stack names, dependencies first. */
  readonly order: string[]
  /** `[dependency, dependent]` pairs, one per stack a `Ref` reaches into. */
  readonly edges: Array<[string, string]>
  readonly specs: Record<string, Spec>
  /** Docker project name per stack — the stack name. */
  readonly projects: Record<string, string>
}

// ---------------- session --------------------------

/** One resolve: the vars in play, and each definition evaluated at most once per stack. */
const session = (options: Options) => {
  const vars = new Map<Var<any>, unknown>(options.vars?.map((b) => [b.var, b.value]))
  const cache = new Map<string, Map<Resource, Promise<unknown>>>()

  const get = <T>(v: Var<T>): T => {
    if (vars.has(v)) return vars.get(v) as T
    if (v.fallback) return v.fallback.value
    throw new Error(`var "${v.name}" was not provided`)
  }

  const evaluate = <K extends Kind>(r: Resource<K>, project: string): Promise<Def[K]> => {
    const done = (cache.get(project) ?? cache.set(project, new Map()).get(project))!
    if (!done.has(r)) {
      const cx: Context = { name: r.name, project, build: options.build ?? false, get }
      done.set(r, (async () => (typeof r.def === 'function' ? r.def(cx) : r.def))())
    }
    return done.get(r) as Promise<Def[K]>
  }

  return evaluate
}

type Evaluate = ReturnType<typeof session>

/**
 * The stub a `Ref` leaves in the stack that uses it. Compose prefixes the project onto an
 * unnamed network/volume/secret/config, so the owner's docker name is derivable without
 * anyone having to pin it.
 */
const external = async (ref: Ref, evaluate: Evaluate): Promise<object> => {
  if (ref.type === 'service') {
    throw new Error(`services cannot be referenced across stacks — reach "${ref.name}" over a shared network`)
  }
  const def = (await evaluate(ref.resource, ref.stack.name)) as { name?: string }
  return { external: true, name: def.name ?? `${ref.stack.name}_${ref.name}` }
}

const build = async (stack: Compose, evaluate: Evaluate): Promise<Spec> => {
  const owners = new Map<string, Resource>()
  const entries: Array<{ type: Kind; name: string; value: Promise<unknown> }> = []

  for (const item of stack.items) {
    const r = isRef(item) ? item.resource : item
    const key = `${item.type}.${item.name}`
    const prev = owners.get(key)
    if (prev === r) continue
    if (prev) throw new Error(`${stack.name}: two different resources are both ${key}`)
    owners.set(key, r)

    const value = isRef(item) ? external(item, evaluate) : evaluate(r, stack.name)
    entries.push({ type: item.type, name: item.name, value })
  }

  const values = await Promise.all(
    entries.map(({ type, name, value }) =>
      value.catch((cause: unknown) => {
        throw new Error(`${stack.name}: ${type}.${name}: ${cause instanceof Error ? cause.message : String(cause)}`, {
          cause,
        })
      }),
    ),
  )

  const spec: Record<string, Record<string, unknown>> = {}
  for (const kind of KINDS) {
    entries.forEach(({ type, name }, i) => {
      if (type === kind) (spec[`${kind}s`] ??= {})[name] = values[i]
    })
  }
  return { name: stack.name, ...spec }
}

// ---------------- entry points --------------------------

/** One stack's compose file. */
export const Resolve = (stack: Compose, options: Options = {}): Promise<Spec> => build(stack, session(options))

/** Every stack's compose file, ordered so each comes up after the stacks it refs into. */
export const Project = async (stacks: readonly Compose[], options: Options = {}): Promise<Project> => {
  const names = stacks.map((s) => s.name)
  const dupe = names.find((n, i) => names.indexOf(n) !== i)
  if (dupe) throw new Error(`duplicate stack "${dupe}"`)

  const edges: Array<[string, string]> = []
  for (const s of stacks) {
    const reached = new Set(s.items.filter(isRef).map((r) => r.stack.name))
    for (const dependency of reached) {
      if (dependency === s.name) continue
      if (!names.includes(dependency))
        throw new Error(`stack "${s.name}" refs into "${dependency}", which is not in this project`)
      edges.push([dependency, s.name])
    }
  }

  const evaluate = session(options)
  const specs = await Promise.all(stacks.map((s) => build(s, evaluate)))

  return {
    order: topological(names, edges),
    edges,
    specs: Object.fromEntries(specs.map((spec) => [spec.name, spec])),
    projects: Object.fromEntries(names.map((n) => [n, n])),
  }
}

/** Kahn's algorithm, stable in declaration order. */
const topological = (nodes: string[], edges: Array<[string, string]>): string[] => {
  const order: string[] = []
  const remaining = new Set(nodes)

  while (remaining.size > 0) {
    const ready = nodes.filter((n) => remaining.has(n) && edges.every(([from, to]) => to !== n || !remaining.has(from)))
    if (ready.length === 0) throw new Error(`cycle between stacks: ${[...remaining].join(' -> ')}`)
    for (const n of ready) {
      order.push(n)
      remaining.delete(n)
    }
  }
  return order
}
